import sys

def days_for_project(a, b, p, q):
    if a == 0 and b == 0:
        return float('inf')
    elif a == 0:
        return q / b
    elif b == 0:
        return p / a
    else:
        return max(p / a, q / b)

def min_days(n, p, q, projects):
    min_days_needed = float('inf')

    for a, b in projects:
        days = days_for_project(a, b, p, q)
        if days < min_days_needed:
            min_days_needed = days

    return min_days_needed

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
